    private List<String> name;

    public Foo() {
        super();
    }

    public Foo(final long id, final List<String> name) {
        super();

        this.id = id;
        this.name = name;
    }

    //

    public long getId() {
        return id;
    }

    public void setId(final long id) {
        this.id = id;
    }

    public List<String> getName() {
        return name;
    }

    public void setName(final List<String> name) {
        this.name = name;
    }

}

